package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	x, _ := strconv.Atoi(strings.Fields(sc.Text())[0])
	// ここから下を書く（{} ブロックの中で x := x * 10 を宣言する）
	_ = x
	_ = fmt.Println
}

